  for (const rawRange of ranges) {
    const range = rawRange.replace(/^[ \t]+|[ \t]+$/g, '');
    if (/^[0-9]+-[0-9]+$/.test(range)) {
      const dash = range.indexOf('-');
      const start = parseInteger(range.slice(0, dash));
      const end = parseInteger(range.slice(dash + 1));
      if (start > end) throw new TypeError('Reversed byte range');
      if (size === 0 || start >= size) continue;
      result.push([start, Math.min(end, size - 1)]);
    } else if (/^[0-9]+-$/.test(range)) {
