    throw new TypeError('CSV input must be a string');
  }
  if (text.length === 0) return [];

  const rows = [];
  let row = [];
  let field = '';
  // 0: field start, 1: unquoted field, 2: quoted field, 3: after closing quote
  let state = 0;

  const endField = () => {
    row.push(field);
    field = '';
    state = 0;
  };
  const endRow = () => {
    endField();
    rows.push(row);
    row = [];
  };

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];

    if (state === 2) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          state = 3;
        }
      } else {
        field += ch;
      }
      continue;
