export const retry = async (fn, options) => {
  const { attempts, baseDelay, maxDelay, shouldRetry, sleep } = options;

  if (!Number.isInteger(attempts) || attempts <= 0) {
    throw new TypeError('attempts must be a positive integer');
  }
  if (!Number.isFinite(baseDelay) || baseDelay < 0) {
    throw new TypeError('baseDelay must be a finite nonnegative number');
  }
  if (!Number.isFinite(maxDelay) || maxDelay < 0) {
    throw new TypeError('maxDelay must be a finite nonnegative number');
  }

  for (let attemptNumber = 1; ; attemptNumber += 1) {
    try {
      return await fn(attemptNumber);
    } catch (error) {
      if (attemptNumber >= attempts || !(await shouldRetry(error, attemptNumber))) {
        throw error;
      }

      await sleep(Math.min(maxDelay, baseDelay * 2 ** (attemptNumber - 1)));
    }
  }
};

