    throw new Error('nodes and edges must be arrays');
  }

  const indexByNode = new Map();
  for (let i = 0; i < nodes.length; i += 1) {
    const node = nodes[i];
    if (typeof node !== 'string') throw new Error('nodes must be strings');
    if (indexByNode.has(node)) throw new Error(`duplicate node: ${node}`);
    indexByNode.set(node, i);
  }

  const outgoing = Array.from({ length: nodes.length }, () => new Set());
  const indegree = Array(nodes.length).fill(0);
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) {
      throw new Error('each edge must be a [from, to] pair');
    }
    const [from, to] = edge;
    if (!indexByNode.has(from) || !indexByNode.has(to)) {
      throw new Error('edge endpoint is not in nodes');
    }
    const fromIndex = indexByNode.get(from);
    const toIndex = indexByNode.get(to);
    if (!outgoing[fromIndex].has(toIndex)) {
      outgoing[fromIndex].add(toIndex);
      indegree[toIndex] += 1;
    }
  }

  const result = [];
  const emitted = Array(nodes.length).fill(false);
  while (result.length < nodes.length) {
    // Scanning in original order selects the earliest among every node that
    // is currently zero-indegree, including nodes made available earlier.
    let next = -1;
    for (let i = 0; i < nodes.length; i += 1) {
      if (!emitted[i] && indegree[i] === 0) {
        next = i;
        break;
      }
    }
    if (next === -1) throw new Error('graph contains a cycle');

    emitted[next] = true;
    result.push(nodes[next]);
    for (const neighbor of outgoing[next]) indegree[neighbor] -= 1;
  }
  return result;
};

