    if (!Number.isFinite(ttl) || ttl < 0 || !Number.isFinite(now)) {
      throw new TypeError('ttl and now must be finite numbers, with ttl >= 0');
    }

    this.#purgeExpired(now);

    // A zero-duration entry is never observable, and setting it still refreshes
    // the key by removing any previous value for that key.
    if (ttl === 0) {
      this.entries.delete(key);
      return;
    }

    // Refreshing an existing key must not evict another entry.
    this.entries.delete(key);
    this.entries.set(key, { value, expires: now + ttl });

    if (this.entries.size > this.capacity) {
      const leastRecentKey = this.entries.keys().next().value;
      this.entries.delete(leastRecentKey);
    }
  }

